use libtmux::CancellationToken;

let token = CancellationToken::new();
let observer = token.clone();
assert!(!observer.is_cancelled());
token.cancel();
assert!(observer.is_cancelled());

let guard = libtmux::test::TestServer::new()?;

// Detected once and cached, so asking twice does not run tmux twice.
let capabilities = guard.server().capabilities()?;
assert!(!capabilities.tmux_version().raw().is_empty());

guard.shutdown()?;

let server = libtmux::Server::new()?;
let capabilities = server.capabilities()?;
assert!(!capabilities.tmux_version().raw().is_empty());
server.shutdown()?;

let guard = libtmux::test::TestServer::new()?;
guard.server().new_session("work")?;

// A session created without attaching has no client, which is the usual
// shape under test and under automation.
assert!(guard.server().clients()?.is_empty());

guard.shutdown()?;

let guard = libtmux::test::TestServer::new()?;
let server = guard.server();
let session = server.new_session("work")?;

// A control-mode connection is a client, so the server has one to find.
let control = libtmux::control::ControlMode::attach(server, session.id())?;
let client = server.clients()?.into_iter().next().expect("one client");

let attached = client.attached_session()?.expect("it is attached");
assert_eq!(attached.id(), session.id());
control.shutdown()?;

guard.shutdown()?;

use libtmux::Client;
use libtmux::query::Filterable as _;

let fields = Client::filter_fields();
for client in server.clients()? {
    // The key table a client is in: `prefix` right after the prefix key.
    if let Some(table) = client.get(fields.client_key_table).available() {
        println!("{client}: {}", table.to_string_lossy());
    }
}

use libtmux::Command;

let command = Command::new("display-message").arg("hello");
assert_eq!(command.summary().argument_count(), 1);

use libtmux::Command;

let command = Command::new("list-sessions");
assert_eq!(command.summary().to_string(), r#""list-sessions""#);

use libtmux::Command;

let command = Command::new("display-message").arg("hello");
assert_eq!(command.summary().public_argument_count(), 1);

use libtmux::Command;

let command = Command::new("set-environment")
    .arg("TOKEN")
    .sensitive_arg("secret");
assert_eq!(command.summary().sensitive_argument_count(), 1);
assert!(!command.summary().to_string().contains("secret"));

use libtmux::Command;

let summary = Command::new("display-message").arg("value;").summary();
assert_eq!(summary.to_string(), r#""display-message" "value;""#);

use libtmux::{Command, CommandChain};

let chain = CommandChain::new(Command::new("send-keys").arg("-t").arg("%1"))
    .then(Command::new("rename-window").arg("-t").arg("@1").arg("edit"));

assert_eq!(chain.command_count(), 2);
assert_eq!(
    chain.summary().to_string(),
    r#""send-keys" "-t" "%1" ; "rename-window" "-t" "@1" "edit""#,
);

use libtmux::{Command, CommandChain};

let chain = CommandChain::new(Command::new("display-message").arg(";"))
    .then(Command::new("list-sessions"));

assert_eq!(
    chain.summary().to_string(),
    r#""display-message" ";" ; "list-sessions""#,
);

use libtmux::{Command, CommandChain};

let chain = CommandChain::new(Command::new("list-sessions"));
assert_eq!(chain.command_count(), 1);

use libtmux::{Command, CommandChain};

let chain = CommandChain::new(Command::new("select-pane").arg("-m"))
    .then(Command::new("select-pane").arg("-M"));
assert_eq!(chain.command_count(), 2);

use libtmux::{Command, CommandChain};

let chain = CommandChain::new(Command::new("list-panes"));
assert_eq!(chain.command_count(), 1);

use libtmux::{Command, CommandChain};

let summary = CommandChain::new(Command::new("select-pane").arg("-m"))
    .then(Command::new("select-pane").arg("-M"))
    .summary();

assert_eq!(summary.to_string(), r#""select-pane" "-m" ; "select-pane" "-M""#);
assert_eq!(summary.public_argument_count(), 3);

use libtmux::Command;

let guard = libtmux::test::TestServer::new()?;
let result = guard
    .server()
    .cmd(
        Command::new("set-environment")
            .arg("-g")
            .arg("TOKEN")
            .sensitive_arg("hunter2"),
    )
    ?;

// The subcommand is not an argument, so this counts `-g`, `TOKEN`, and
// the secret.
let summary = result.command();
assert_eq!(summary.argument_count(), 3);
assert_eq!(summary.public_argument_count(), 2);

// The secret is neither shown nor measurable from what is shown.
let rendered = summary.to_string();
assert!(!rendered.contains("hunter2"), "{rendered}");
assert!(!format!("{summary:?}").contains("hunter2"));

guard.shutdown()?;

use libtmux::Command;

let summary = Command::new("set-option").arg("-g").arg("mouse").summary();
assert_eq!(summary.argument_count(), 2);

use libtmux::Command;

let summary = Command::new("set-option").arg("mouse").summary();
assert_eq!(summary.public_argument_count(), 1);

use libtmux::Command;

let summary = Command::new("set-environment").sensitive_arg("secret").summary();
assert_eq!(summary.sensitive_argument_count(), 1);

use libtmux::Command;

let guard = libtmux::test::TestServer::new()?;
guard.server().new_session("work")?;

let result = guard
    .server()
    .cmd(Command::new("list-sessions").arg("-F").arg("#{session_name}"))
    ?;

// The exact bytes tmux emitted are kept until a caller asks for text, because
// a session name need not be UTF-8.
assert_eq!(result.stdout(), b"work\n");
assert_eq!(result.stdout_utf8()?, "work\n");

guard.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-id.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
assert!(result.request_id() > 0);
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-command.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
assert_eq!(result.command().to_string(), r#""list-sessions""#);
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-stdout.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
let _: &[u8] = result.stdout();
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-stderr.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
let _: &[u8] = result.stderr();
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-streams.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
let (_stdout, _stderr) = result.into_streams();
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-stdout-utf8.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
let _text = result.stdout_utf8()?;
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-stderr-utf8.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
let _text = result.stderr_utf8()?;
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-stdout-lossy.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
let _text = result.stdout_lossy();
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-stderr-lossy.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
let _text = result.stderr_lossy();
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-success.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
let _success = result.success();
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-code.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
assert!(result.exit_code().is_some());
server.shutdown()?;

let server = libtmux::Server::builder().socket_path("/tmp/libtmux-rs-test/result-signal.sock").build()?;
let result = server.cmd(libtmux::Command::new("list-sessions"))?;
assert!(result.signal().is_none());
server.shutdown()?;

use libtmux::control::Subscription;

assert_eq!(Subscription::AllPanes.to_string(), "%*");
assert_eq!(Subscription::AllWindows.to_string(), "@*");

// The session the connection is attached to, named by naming nothing.
assert_eq!(Subscription::Session.to_string(), "");

use libtmux::control::{ControlMode, Event, Subscription};

let guard = libtmux::test::TestServer::new()?;
let session = guard.server().new_session("watched")?;
let (commands, mut events) = ControlMode::attach(guard.server(), session.id())
    ?
    .split();

commands
    .subscribe("title", &Subscription::Session, "#{session_name}")
    ?;

// The first report arrives without anything having changed, which is
// what makes a subscription usable for reading the value as well.
while let Some(event) = events.next_event() {
    if let Event::SubscriptionChanged { name, value, .. } = event? {
        assert_eq!(name.as_str()?, "title");
        assert_eq!(value.as_str()?, "watched");
        break;
    }
}

commands.unsubscribe("title")?;
events.shutdown()?;

let mut output = pane.stream_output()?;
let mut preceding = Vec::new();
let visible = output.snapshot(|chunk| preceding.extend_from_slice(chunk))?;

println!("{} visible lines after {} raw bytes", visible.len(), preceding.len());
output.shutdown()

use libtmux::{Error, ServerConfigurationErrorKind};

// A socket name and a socket path are two ways to say the same thing, and
// tmux has no rule for which wins, so the builder refuses rather than picks.
let failure = libtmux::Server::builder()
    .socket_name("named")
    .socket_path("/tmp/libtmux-rs-dev/explicit")
    .build()
    .expect_err("two socket selectors");

assert!(matches!(
    failure,
    Error::InvalidServerConfiguration {
        kind: ServerConfigurationErrorKind::ConflictingSocketSelectors,
        ..
    },
));

// The rejected bytes are not carried in the error, so logging it cannot
// disclose a path.
assert!(!failure.to_string().contains("/tmp/"));

use libtmux::{Error, OptionErrorKind};

fn advise(error: &Error) -> &'static str {
    match error {
        Error::OptionRejected { kind, .. } => match kind {
            OptionErrorKind::Unknown => "check the spelling",
            OptionErrorKind::Ambiguous => "write more of the name",
            OptionErrorKind::BadValue => "the option will not hold that",
            _ => "tmux refused it",
        },
        _ => "not an option problem",
    }
}

let refused = Error::OptionRejected {
    kind: OptionErrorKind::Ambiguous,
    detail: "status-l".to_owned(),
};
assert_eq!(advise(&refused), "write more of the name");

use libtmux::{Error, ServerGoneKind};

fn advise(error: &Error) -> &'static str {
    match error {
        Error::ServerGone { kind, .. } => match kind {
            ServerGoneKind::NotRunning => "start one",
            ServerGoneKind::Unreachable => "check the socket path",
            ServerGoneKind::Lost | ServerGoneKind::Stopped => "it went away mid-command",
            _ => "there is no server",
        },
        _ => "not a server problem",
    }
}

let absent = Error::ServerGone {
    command: "list-sessions",
    kind: ServerGoneKind::NotRunning,
};
assert_eq!(advise(&absent), "start one");

use libtmux::ErrorKind;

fn target_is_stale(kind: ErrorKind) -> bool {
    matches!(kind, ErrorKind::ObjectGone)
}

assert!(target_is_stale(ErrorKind::ObjectGone));
assert!(!target_is_stale(ErrorKind::InvalidInput));

use libtmux::ErrorKind;

let guard = libtmux::test::TestServer::new()?;
let doomed = guard.server().new_session("doomed")?;
let mut stale = doomed.clone();
guard.server().new_session("survivor")?;
doomed.kill()?;

// A handle outliving its object is the normal way this fails, so
// `is_object_gone` is the branch most callers write.
let failure = stale.rename("renamed").expect_err("the session is gone");
assert!(failure.is_object_gone());
assert_eq!(failure.kind(), ErrorKind::ObjectGone);

guard.shutdown()?;

