examples.code:
use libtmux::ObjectKind;

// Carried by `Error::ObjectGone` so a caller can say what disappeared
// without parsing the message.
assert_eq!(ObjectKind::Pane.to_string(), "pane");

use libtmux::Error;

// Reached through the one variant that carries it. Both accessors are
// optional because tmux does not always give enough to locate the row.
fn locate(failure: &Error) -> Option<(&'static str, Option<usize>)> {
    match failure {
        Error::DecodeListing { list_command, detail, .. } => {
            Some((*list_command, detail.row()))
        }
        _ => None,
    }
}

// The payload is metadata only: no tmux bytes are retained, so logging it
// cannot leak a pane's contents.
let other = libtmux::Server::builder()
    .socket_name("named")
    .socket_path("/tmp/libtmux-rs-dev/explicit")
    .build()
    .expect_err("two socket selectors");
assert_eq!(locate(&other), None);

use libtmux::TmuxVersion;

let output = b"invalid\n";
let error = TmuxVersion::parse_output(output).expect_err("output is invalid");
assert_eq!(error.invalid_version_output_len(), Some(output.len()));

use libtmux::TmuxVersion;

let version = TmuxVersion::parse_output(b"tmux 3.2\n")?;
let error = version.ensure_supported().expect_err("3.2 is unsupported");
assert_eq!(error.found_version(), Some(&version));

use libtmux::TmuxVersion;

let version = TmuxVersion::parse_output(b"tmux 3.2\n")?;
let error = version.ensure_supported().expect_err("3.2 is unsupported");
assert_eq!(error.minimum_version(), Some(&TmuxVersion::MIN_SUPPORTED));

use libtmux::ErrorKind;

// The shape this exists for: use it if it is there, make it if not.
let session = match server.session("work")? {
    Some(session) => session,
    None => server.new_session("work")?,
};

// And when an operation races something else removing it. The handle
// is cloned because killing consumes one, which is how the crate
// stops you from using a window you just destroyed.
let window = session.new_window("doomed")?;
let mut stale = window.clone();
window.kill()?;

let error = stale.rename("gone").expect_err("the window was killed");
assert_eq!(error.kind(), ErrorKind::ObjectGone);
assert!(error.is_object_gone());

use libtmux::ScopeError;

let guard = libtmux::test::TestServer::new()?;
let outcome = guard.server().with_session("work",  |_session| {
    Err::<(), _>("operation failed")
});
assert!(matches!(outcome, Err(ScopeError::Operation("operation failed"))));
guard.shutdown()?;

use libtmux::ScopeError;

let failed: ScopeError<(), _> = ScopeError::Operation("no route");
assert_eq!(failed.into_operation(), Some("no route"));

// The work is done even when tearing the session down failed, so the
// value is worth keeping rather than discarding with the error.
let outcome = server
    .with_session("build",  |session| {
        Ok::<_, libtmux::Error>(session.id().to_string())
    })
    ;

let id = match outcome {
    Ok(id) => Some(id),
    Err(error) => error.into_value(),
};

use libtmux::ScopeError;

let failed: ScopeError<(), &str> = ScopeError::Operation("no route");
assert!(failed.tmux_error().is_none());

let guard = libtmux::test::TestServer::new()?;
let server = guard.server();

server.set_hook("after-new-window", "display-message built")?;
let hooks = server.hook("after-new-window")?.expect("the hook is set");

assert_eq!(hooks.len(), 1);
assert_eq!(
    hooks.first().map(|value| value.to_string_lossy().into_owned()),
    Some("display-message built".to_owned()),
);

guard.shutdown()?;

use libtmux::{IndexedHooks, ReplaceMode, TmuxText};
use std::collections::BTreeMap;

let guard = libtmux::test::TestServer::new()?;
let server = guard.server();

// The indices are tmux's own and are sparse: removing one does not renumber
// the rest, so the map is keyed rather than positional.
let mut entries = BTreeMap::new();
entries.insert(0, TmuxText::from("display-message first"));
entries.insert(4, TmuxText::from("display-message fifth"));
server
    .set_hooks("after-new-window", &IndexedHooks::from(entries), ReplaceMode::Replace)
    ?;

let hooks: IndexedHooks = server.hook("after-new-window")?.expect("just written");
assert_eq!(hooks.len(), 2);
assert_eq!(hooks.indices().copied().collect::<Vec<_>>(), vec![0, 4]);

guard.shutdown()?;

use libtmux::{IndexedHooks, ReplaceMode, TmuxText};
use std::collections::BTreeMap;

let guard = libtmux::test::TestServer::new()?;
let server = guard.server();

let mut first = BTreeMap::new();
first.insert(0, TmuxText::from("display-message one"));
first.insert(1, TmuxText::from("display-message two"));
server
    .set_hooks("after-new-window", &IndexedHooks::from(first), ReplaceMode::Replace)
    ?;

// `Merge` writes the indices it names and leaves the rest alone.
let mut second = BTreeMap::new();
second.insert(1, TmuxText::from("display-message replaced"));
server
    .set_hooks("after-new-window", &IndexedHooks::from(second), ReplaceMode::Merge)
    ?;

let hooks = server.hook("after-new-window")?.expect("just written");
assert_eq!(hooks.len(), 2);

guard.shutdown()?;

use libtmux::OutputLimits;

// The default is roomy enough for a pane with a very long history.
assert_eq!(OutputLimits::default().stdout_bytes(), 32 * 1024 * 1024);

// Tighten it where the caller knows the answer is small.
let limits = OutputLimits::default().max_stdout_bytes(64 * 1024);
assert_eq!(limits.stdout_bytes(), 64 * 1024);

use libtmux::DispatchLimits;

let limits = DispatchLimits::default().max_in_flight(4);
assert_eq!(limits.in_flight(), 4);

use libtmux::ControlClientLimits;

let limits = ControlClientLimits::default().max_clients(4);
assert_eq!(limits.clients(), 4);

use libtmux::ControlLimits;

let limits = ControlLimits::default().max_line_bytes(4096);
assert_eq!(limits.line_bytes(), 4096);

use libtmux::{OptionKind, option_schema};

// `mouse` is a real flag: on or off.
assert_eq!(option_schema("mouse").map(OptionSchema::kind), Some(OptionKind::Flag));

// `status` looks like one and is not: it also accepts a count of status
// lines, so reading it as a boolean discards those values.
assert_eq!(option_schema("status").map(OptionSchema::kind), Some(OptionKind::Choice));

use libtmux::{OptionScope, option_schema};

// The scope says which handle can set an option, which is not guessable
// from the name: `mouse` is per-session, and `exit-empty` is server-wide.
assert!(option_schema("mouse").is_some_and(|o| o.accepts(OptionScope::Session)));
assert!(option_schema("exit-empty").is_some_and(|o| o.accepts(OptionScope::Server)));

// Some options live in two tables at once, and tmux takes a write at
// either. Asking for one scope would have to pick, and picking is wrong.
let remain = option_schema("remain-on-exit").expect("a documented option");
assert_eq!(remain.scopes(), [OptionScope::Window, OptionScope::Pane]);

use libtmux::{OptionKind, OptionScope, option_schema};

let schema = option_schema("history-limit").expect("a documented option");
assert_eq!(schema.name(), "history-limit");
assert_eq!(schema.kind(), OptionKind::Number);
assert_eq!(schema.scopes(), [OptionScope::Session]);
assert!(schema.accepts(OptionScope::Session));

// An option tmux does not have has no schema, which catches a typo before it
// reaches the server.
assert!(option_schema("history-limits").is_none());

use libtmux::option_schema;

let keys = option_schema("mode-keys").expect("a documented option");
assert_eq!(keys.choices(), ["emacs", "vi"]);

let limit = option_schema("history-limit").expect("a documented option");
assert!(limit.choices().is_empty());

use libtmux::option_schema;

let limit = option_schema("buffer-limit").expect("a documented option");
assert_eq!(limit.range(), Some(1..=i64::from(i32::MAX)));

let keys = option_schema("mode-keys").expect("a documented option");
assert_eq!(keys.range(), None);

use libtmux::{OptionKind, OptionValueRefusal};

fn advise(refusal: &OptionValueRefusal) -> String {
    match refusal {
        OptionValueRefusal::WrongKind { expected } => format!("pass a {expected:?}"),
        OptionValueRefusal::NotAChoice { choices } => format!("pick one of {choices:?}"),
        OptionValueRefusal::OutOfRange { range } => format!("stay within {range:?}"),
        _ => "check the value".to_owned(),
    }
}

let refusal = OptionValueRefusal::WrongKind { expected: OptionKind::Flag };
assert_eq!(advise(&refusal), "pass a Flag");

use libtmux::{OptionKind, option_schema};

// `status` looks like a flag but accepts on, off, and 2 through 5, so
// tmux declares it a choice. The schema records that rather than guessing.
assert_eq!(option_schema("status").map(|o| o.kind()), Some(OptionKind::Choice));
assert_eq!(option_schema("mouse").map(|o| o.kind()), Some(OptionKind::Flag));
assert_eq!(option_schema("history-limit").map(|o| o.kind()), Some(OptionKind::Number));
assert_eq!(option_schema("after-new-window[0]").map(|o| o.kind()), Some(OptionKind::Command));
assert_eq!(option_schema("@mine"), None);

use libtmux::{Error, OptionValue, OptionValueRefusal};

let guard = libtmux::test::TestServer::new()?;
let server = guard.server();
server.new_session("typed")?;

// `mouse` is a flag, so it is written and read back as one.
server.set_typed_global_option("mouse", true)?;
assert_eq!(server.typed_global_option("mouse")?, Some(OptionValue::Flag(true)));

// `status` also reads `on`, and is *not* a flag: tmux accepts `on`, `off`,
// and `2` through `5`. Inferring the type from the value would call this a
// boolean and then fail on a value that is not one, which is why the
// schema is generated from tmux's own option table instead.
let status = server.typed_global_option("status")?.expect("status is set");
assert!(matches!(status, OptionValue::Text(_)));

// A word tmux's table does not list for a choice is refused unsent.
let refused = server
    .set_typed_global_option("status-position", "sideways")

    .expect_err("not a position tmux has");
assert!(matches!(
    refused,
    Error::OptionValueRefused { reason: OptionValueRefusal::NotAChoice { .. }, .. },
));

guard.shutdown()?;

let guard = libtmux::test::TestServer::new()?;
let session = guard.server().new_session("work")?;
let window = session.active_window()?.expect("a session has a window");
let pane = window.active_pane()?.expect("a window has a pane");

pane.send_line("echo hello")?;

// Capture returns `TmuxText`, because a pane can print any bytes.
let lines = pane.capture()?;
assert!(!lines.is_empty());

guard.shutdown()?;

use libtmux::Pane;

let session = server.new_session("locating")?;
let expected = session.panes()?.remove(0);

// Standing in for the environment tmux gives a process it starts.
