use libtmux::query::FilterExpr;

#[derive(libtmux::Filterable)]
#[filterable(target = "task")]
struct Task {
    name: String,
    done: bool,
}

let schema = schemars::schema_for!(FilterExpr<Task>);
assert!(schema.as_object().is_some());

use libtmux::CancellationToken;

let token = CancellationToken::new();
let observer = token.clone();
assert!(!observer.is_cancelled());
token.cancel();
assert!(observer.is_cancelled());

use libtmux::SessionId;

// The sigil is the whole difference between the id types, so a mistake
// names the one that was expected.
let error = "@1".parse::<SessionId>().expect_err("@ denotes a window");
assert_eq!(error.expected_sigil(), '$');

use libtmux::SessionId;

let error = "@1".parse::<SessionId>().expect_err("@ denotes a window");
assert_eq!(error.expected_sigil(), '$');

use libtmux::TmuxText;

let borrowed = TmuxText::from("session");
let owned = TmuxText::from(String::from("window"));
let bytes = TmuxText::from(vec![b'p', 0xff]);

assert_eq!(borrowed.as_bytes(), b"session");
assert_eq!(owned.as_bytes(), b"window");
assert_eq!(bytes.as_bytes(), [b'p', 0xff]);

use libtmux::TmuxText;

let text = TmuxText::from_bytes(vec![0, 0xff]);
assert_eq!(text.as_bytes(), [0, 0xff]);

use libtmux::TmuxText;

let text = TmuxText::from_bytes(vec![b'a', 0xff]);
assert_eq!(text.as_bytes(), [b'a', 0xff]);

use libtmux::TmuxText;

let text = TmuxText::from("session");
assert_eq!(text.as_str(), Ok("session"));

use libtmux::TmuxText;

let text = TmuxText::from_bytes(vec![b'a', 0xff]);
assert_eq!(text.to_string_lossy(), "a\u{fffd}");

use libtmux::TmuxText;

assert_eq!(TmuxText::from("on").as_flag(), Some(true));
assert_eq!(TmuxText::from("off").as_flag(), Some(false));
assert_eq!(TmuxText::from("sometimes").as_flag(), None);

use libtmux::TmuxText;

assert_eq!(TmuxText::from("2000").parse::<u32>(), Some(2000));
assert_eq!(TmuxText::from("many").parse::<u32>(), None);

use libtmux::PaneId;

let second: PaneId = "%2".parse()?;
let tenth: PaneId = "%10".parse()?;
assert!(second < tenth);

use libtmux::SessionId;

let id: SessionId = "$001".parse()?;
assert_eq!(id.as_ref(), "$1");

use libtmux::SessionName;

assert!(SessionName::new("build").is_ok());
assert!(SessionName::new("a:b").is_err());
assert!(SessionName::new("c.d").is_err());
assert!(SessionName::new("").is_err());

// Everything else tmux accepts is kept, including what looks awkward.
assert!(SessionName::new("has,comma").is_ok());
assert!(SessionName::new("has space").is_ok());

use libtmux::{SessionName, SessionNameError};

// tmux splits a target on `:` and `.`, so a name holding either would not be
// addressable by name afterwards.
assert!(matches!(
    SessionName::new("build:release"),
    Err(SessionNameError::Separator { separator: ':' }),
));
assert!(matches!(SessionName::new(""), Err(SessionNameError::Empty)));
assert!(SessionName::new("build-release").is_ok());

use libtmux::TmuxArg;

// The ordinary path. `From` escapes, so tmux stores what was asked.
let literal = TmuxArg::from("release#1");
assert_eq!(literal.as_os_str(), "release##1");

// Expansion is opt-in and reads as such.
let expanded = TmuxArg::format("#{pane_current_path}");
assert_eq!(expanded.as_os_str(), "#{pane_current_path}");

use libtmux::WindowId;

let id: WindowId = "@10".parse()?;
assert_eq!(id.to_string(), "@10");

use std::ffi::OsString;

use libtmux::escape_format;

// Text that would otherwise run a command.
assert_eq!(escape_format("#(id)"), OsString::from("##(id)"));

// Ordinary text is unchanged.
assert_eq!(escape_format("editor"), OsString::from("editor"));

use libtmux::{ReleaseSuffix, ReleaseVersion};

// tmux's two suffix shapes order differently: a patch letter comes *after*
// the plain release, and a release candidate comes before it.
let plain = ReleaseVersion::new(3, 5, ReleaseSuffix::FINAL);
let patched = ReleaseVersion::new(3, 5, ReleaseSuffix::patch('a').expect("a patch letter"));
let candidate = ReleaseVersion::new(
    3,
    5,
    ReleaseSuffix::release_candidate(1).expect("one is nonzero"),
);

assert!(candidate < plain);
assert!(plain < patched);

// Only those two shapes exist, so anything else is rejected rather than
// guessed at.
assert_eq!(ReleaseSuffix::patch('B'), None);
assert_eq!(ReleaseSuffix::release_candidate(0), None);

use libtmux::ReleaseSuffix;

let suffix = ReleaseSuffix::release_candidate(2).expect("two is nonzero");
assert_eq!(suffix.release_candidate_number(), Some(2));
assert_eq!(ReleaseSuffix::release_candidate(0), None);

use libtmux::ReleaseSuffix;

let suffix = ReleaseSuffix::patch('b').expect("b is a patch letter");
assert_eq!(suffix.patch_letter(), Some('b'));
assert_eq!(ReleaseSuffix::patch('B'), None);

use libtmux::ReleaseSuffix;

assert_eq!(ReleaseSuffix::FINAL.patch_letter(), None);
assert_eq!(ReleaseSuffix::patch('a').and_then(|value| value.patch_letter()), Some('a'));

use libtmux::ReleaseSuffix;

assert_eq!(ReleaseSuffix::RELEASE_CANDIDATE.release_candidate_number(), Some(1));
assert_eq!(ReleaseSuffix::FINAL.release_candidate_number(), None);

use libtmux::ReleaseSuffix;

assert!(ReleaseSuffix::FINAL.is_final());
assert!(!ReleaseSuffix::RELEASE_CANDIDATE.is_final());

use libtmux::ReleaseSuffix;

assert!(ReleaseSuffix::RELEASE_CANDIDATE.is_release_candidate());
assert!(!ReleaseSuffix::FINAL.is_release_candidate());

use libtmux::{ReleaseSuffix, ReleaseVersion};

// tmux numbers a patch with a letter, so `3.5a` is later than `3.5`.
let plain = ReleaseVersion::new(3, 5, ReleaseSuffix::FINAL);
let patched = ReleaseVersion::new(3, 5, ReleaseSuffix::patch('a').expect("a patch letter"));
assert!(patched > plain);

use libtmux::{ReleaseSuffix, ReleaseVersion};

let release = ReleaseVersion::new(3, 7, ReleaseSuffix::FINAL);
assert_eq!(release.to_string(), "3.7");

use libtmux::{ReleaseSuffix, ReleaseVersion};

let release = ReleaseVersion::new(3, 7, ReleaseSuffix::FINAL);
assert_eq!(release.major(), 3);

use libtmux::{ReleaseSuffix, ReleaseVersion};

let release = ReleaseVersion::new(3, 7, ReleaseSuffix::FINAL);
assert_eq!(release.minor(), 7);

use libtmux::{ReleaseSuffix, ReleaseVersion};

let release = ReleaseVersion::new(3, 7, ReleaseSuffix::RELEASE_CANDIDATE);
assert_eq!(release.suffix(), ReleaseSuffix::RELEASE_CANDIDATE);

